pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        address target = address(0x123);
        vm.deal(address(c), 1 ether);
        vm.deal(address(this), 1 ether);
        // Fund the contract so sendMoney call won't fail due to insufficient balance
        // The target is an EOA (no code), so sendMoney will call it with value=0
        // and the fallback will still be triggered on the sender (c) via deposit logic
        // Actually we need target to be a contract that reverts, so sendMoney reverts overall
        // But we want depositsCount to change. The reference calls fallback(), bug does not.
        // Let's use a simple non-reverting target EOA to ensure call succeeds.
        // The fallback is triggered when c receives ether via the call, but the call is from c to target
        // Wait: the sendMoney function does _target.call{value: _value}(_data) — this sends value from c to target.
        // If target is a contract with a receive function, its receive is called, not c's fallback.
        // The key: the fallback in C is triggered only when someone sends ether to c (the contract itself).
        // But here, sendMoney sends ether from c to target. That does NOT call c's fallback.
        // The depositsCount only changes when someone calls c's fallback by sending ether to c.
        // So we need to send ether to c, not call sendMoney.
        // The original difference: P's fallback increments, M's does not.
        vm.deal(address(0xAlice), 1 ether);
        vm.prank(address(0xAlice));
        (bool success, ) = address(c).call{value: 0}();
        // This triggers fallback: P increments, M doesn't
        assertEq(c.depositsCount(), 1);
    }
}

