        vm.etch(target, abi.encodePacked(type(AlwaysRevert).runtimeCode));

        // Ensure owner (this contract) has no ether
        uint initialCount = c.depositsCount();

        // Call sendMoney with 0 value, the target reverts
        // In reference, the whole tx reverts, depositsCount unchanged
