    function testRegression_property() public {
        // Fund the contract so it can send
        vm.deal(address(c), 1 ether);
        uint256 balanceBefore = address(c).balance;

        // Call sendMoney to self with value 1 wei
        // This should revert in reference because fallback is payable but sending to self
        // via call with value from the contract itself fails? Actually we need a target that reverts.
        // Let's use a non-payable address: create a contract that reverts on receive
        // But we cannot create contracts. Instead: send to an address with no fallback
        // A simple EOA (address(0xdead)) will accept ETH, not revert.
        // To force a revert, send to a contract that reverts: we can use the zero address
        // which has no code, so call succeeds (no revert). Hmm.
        // Better approach: send to the contract itself via its own address.
        // The reference requires that the call to _target.call{value: _value}(_data) reverts if the call fails.
        // If we send to address(c), the fallback is payable and increments depositsCount, not reverts.
        // To force a revert, we need a target that reverts. Let's deploy a simple reverting contract
        // within setUp by creating a new C? No, we can't create additional contracts.
        // Use a pre-existing address that always reverts: address(0x1) has no code, call succeeds (no revert).
        // Actually sending to an EOA without receive/fallback will revert if value > 0 (Solidity 0.8.x).
        // address(this) has a payable fallback so it will accept.
        // Use a randomly generated address with no code and no fallback: address(0x1234).
        // Such address receiving ETH will revert because no receive/fallback.

        address target = address(0x1234);
        uint256 value = 1 wei;
        uint256 balanceBeforeCall = address(c).balance;

        // Execute sendMoney - in reference this should revert, in bug it won't
        bool ok;
        try c.sendMoney(target, value, "") {
            ok = true;
        } catch {
            ok = false;
        }

        // In reference: revert happens, balance stays same, ok = false
        // In bug: no revert, balance decreases by value, ok = true
        assertTrue(ok == false); // reference holds (reverts), bug breaks (doesn't revert)
    }
}

