pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        uint initialBalance = 10 ether;
        uint sendValue = 1 wei;
        vm.deal(address(c), initialBalance);
        // sendMoney to the contract itself - this will call the fallback which is payable,
        // but sending to self via low-level call with value is allowed, so reference succeeds.
        // Actually the bug is about revert when call fails; sending to self works, so we need a failing call.
        // Let's use an EOA with no receive/fallback.
        address target = address(0x123);
        vm.deal(address(c), initialBalance);
        bool ok;
        try c.sendMoney(target, sendValue, "") {
            ok = true;
        } catch {
            ok = false;
        }
        // Reference reverts (ok = false) because target has no receive;
        // Buggy does not revert (ok = true) and balance decreases.
        if (ok) {
            // buggy: balance decreased
            assertTrue(address(c).balance == initialBalance - sendValue);
        } else {
            // reference: balance unchanged
            assertTrue(address(c).balance == initialBalance);
        }
        // Actually we need a single assertion that holds for reference and fails for bug.
        // Better: assert that balance is unchanged (true for reference, false for bug).
        // But reference reverts so balance unchanged. Bug does not revert, balance decreased.
        // So we assert balance == initialBalance. Reference passes, bug fails.
        assertTrue(address(c).balance == initialBalance);
    }
}

